package com.findit.servlet;import com.findit.dao.ItemDAO;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.sql.SQLException;@WebServlet("/matches") public class MatchesServlet extends HttpServlet{protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{HttpSession s=q.getSession(false);if(s==null||s.getAttribute("userId")==null){p.sendRedirect(q.getContextPath()+"/login");return;}try{int id=Integer.parseInt(q.getParameter("id"));ItemDAO d=new ItemDAO();q.setAttribute("sourceItem",d.get(id));q.setAttribute("matches",d.matches(id));q.getRequestDispatcher("/WEB-INF/views/matches.jsp").forward(q,p);}catch(NumberFormatException|SQLException e){throw new ServletException(e);}}}
